// ---- src/battle/Unit.js ----
let uidCounter = 0;

class Unit {
  constructor(config) {
    this.uid = `u${uidCounter++}`;
    this.id = config.id;
    this.name = config.name;
    this.isEnemy = !!config.isEnemy;
    this.role = config.role || null;

    this.maxHp = config.maxHp;
    this.hp = config.hp ?? config.maxHp;
    this.maxMp = config.maxMp ?? 0;
    this.mp = config.mp ?? this.maxMp;

    this.atk = config.atk ?? 10;
    this.def = config.def ?? 10;
    this.magic = config.magic ?? 10;
    this.agility = config.agility ?? 20;

    this.weakness = config.weakness ?? null; // element string
    this.resist = config.resist ?? null;
    this.weaponElement = config.weaponElement ?? null;
    this.weaponId = config.weaponId ?? 'w_neutral';
    this.baseAtk = config.baseAtk ?? this.atk;
    this.equippedAbilitySet = config.equippedAbilitySet ?? 'たたかう型';
    this.equipment = config.equipment ?? {
      weapon: null,
      shield: null,
      head: null,
      body: null,
      accessory: null,
    };
    this.abilityId = config.abilityId ?? 'ability_guard';
    this.crystalShardId = config.crystalShardId ?? 'shard_azure';

    this.size = config.size ?? 1.0;
    this.ai = config.ai ?? null;

    // CTB state
    this.ctValue = config.ctValue ?? Math.random() * 200; // slight stagger at battle start
    this.defending = false;

    this.magicList = config.magicList ?? [];
  }

  isAlive() {
    return this.hp > 0;
  }

  applyDamage(amount) {
    const dmg = Math.max(0, Math.round(amount));
    this.hp = Math.max(0, this.hp - dmg);
    return dmg;
  }

  applyHeal(amount) {
    const before = this.hp;
    this.hp = Math.min(this.maxHp, this.hp + Math.round(amount));
    return this.hp - before;
  }

  spendMp(amount) {
    this.mp = Math.max(0, this.mp - amount);
  }

  hpRatio() {
    return this.hp / this.maxHp;
  }
}

// ---- src/battle/ActionResolver.js ----
/**
 * ActionResolver
 * Pure(ish) functions that turn an "action" declaration into concrete
 * HP/MP changes on the involved units. Kept separate from BattleManager so
 * the math can be unit-tested / tweaked independently of turn flow.
 */

const VARIANCE = 0.15; // +/-15% randomness on damage

function randomVariance(base) {
  const factor = 1 + (Math.random() * 2 - 1) * VARIANCE;
  return base * factor;
}

/** Physical attack damage: ATK vs DEF, with a defend-state cut. */
function resolvePhysicalDamage(attacker, defender) {
  const raw = Math.max(1, attacker.atk * 2.2 - defender.def * 1.1);
  let dmg = randomVariance(raw);
  if (attacker.weaponElement && defender.weakness === attacker.weaponElement) dmg *= 1.5;
  if (attacker.weaponElement && defender.resist === attacker.weaponElement) dmg *= 0.5;
  if (defender.defending) dmg *= 0.5;
  return Math.max(1, Math.round(dmg));
}

/** Magic/elemental damage: MAGIC stat * spell power, weakness/resist modifiers. */
function resolveMagicDamage(caster, defender, spell) {
  const raw = Math.max(1, caster.magic * 2.6 * (spell.power ?? 1.0) - defender.def * 0.4);
  let dmg = randomVariance(raw);

  if (spell.element) {
    if (defender.weakness === spell.element) dmg *= 1.75;
    if (defender.resist === spell.element) dmg *= 0.4;
  }
  if (defender.defending) dmg *= 0.5;
  return Math.max(1, Math.round(dmg));
}

/** Heal amount, with light randomness. */
function resolveHeal(amount) {
  return Math.max(1, Math.round(randomVariance(amount)));
}

/**
 * Resolve a full action given the actor, the chosen action definition,
 * and the target(s). Returns a log-friendly result object.
 */
function resolveAction({ actor, action, targets }) {
  const results = [];

  switch (action.kind) {
    case 'physical-attack': {
      const target = targets[0];
      const dmg = resolvePhysicalDamage(actor, target);
      const dealt = target.applyDamage(dmg);
      results.push({ type: 'damage', targetUid: target.uid, amount: dealt });
      break;
    }
    case 'magic-attack': {
      const target = targets[0];
      actor.spendMp(action.mpCost ?? 0);
      const dmg = resolveMagicDamage(actor, target, action);
      const dealt = target.applyDamage(dmg);
      const isWeak = target.weakness === action.element;
      results.push({ type: 'damage', targetUid: target.uid, amount: dealt, weak: isWeak });
      break;
    }
    case 'heal': {
      const target = targets[0];
      if (action.mpCost) actor.spendMp(action.mpCost);
      const healed = target.applyHeal(resolveHeal(action.healAmount));
      results.push({ type: 'heal', targetUid: target.uid, amount: healed });
      break;
    }
    case 'defend': {
      actor.defending = true;
      results.push({ type: 'defend', targetUid: actor.uid });
      break;
    }
    default:
      break;
  }

  return results;
}

// ---- src/battle/CTBEngine.js ----
/**
 * CTBEngine
 * ----------
 * Reproduces the core feel of FFX's Count/Charge Time Battle system:
 *  - Every unit accrues "CT" each tick, proportional to its Agility.
 *  - When a unit's CT crosses BASE_THRESHOLD, it becomes ready to act.
 *  - Acting consumes CT: the action's `ctbCost` multiplier decides how far
 *    the unit's CT drops below the threshold, i.e. how long until its next
 *    turn. Cheap/fast actions (Defend) barely delay the unit; heavy spells
 *    delay it a lot.
 *  - previewQueue() runs a side simulation (cloned CT values only) to show
 *    the upcoming turn order without mutating real battle state.
 */
const BASE_THRESHOLD = 1000;

class CTBEngine {
  constructor(units) {
    this.units = units;
  }

  aliveUnits() {
    return this.units.filter((u) => u.isAlive());
  }

  /**
   * Advances real CT values tick by tick until exactly one unit is ready,
   * then returns that unit. Ties are broken by whichever accumulated the
   * highest CT overshoot, then by Agility.
   */
  advanceToNextActor() {
    const alive = this.aliveUnits();
    if (alive.length === 0) return null;

    // Fast-forward: compute, per unit, how many ticks until threshold, then
    // jump straight to the smallest requirement instead of looping tick by tick.
    // (Still tick-accurate for tie-breaking.)
    let guard = 0;
    while (guard++ < 100000) {
      const ready = alive.filter((u) => u.ctValue >= BASE_THRESHOLD);
      if (ready.length > 0) {
        ready.sort((a, b) => (b.ctValue - a.ctValue) || (b.agility - a.agility));
        return ready[0];
      }
      // Jump forward by the minimum number of ticks needed for the fastest
      // unit-to-threshold gap, applied to everyone at once (equivalent to
      // simulating tick-by-tick, just faster).
      const ticksNeeded = alive.map((u) =>
        Math.ceil((BASE_THRESHOLD - u.ctValue) / Math.max(1, u.agility))
      );
      const jump = Math.max(1, Math.min(...ticksNeeded));
      alive.forEach((u) => {
        u.ctValue += u.agility * jump;
      });
    }
    return alive[0];
  }

  /** Consumes the acting unit's turn, applying the action's CTB cost. */
  consumeTurn(unit, ctbCost = 1.0) {
    unit.ctValue -= BASE_THRESHOLD * ctbCost;
    if (unit.ctValue < -BASE_THRESHOLD * 2) {
      // safety clamp so a single huge cost can't strand a unit forever
      unit.ctValue = -BASE_THRESHOLD * 2;
    }
  }

  /**
   * Predicts the next `count` actors without mutating real units.
   * Enemies are assumed to use a "normal" (1.0) cost action; this is only
   * a preview so perfect accuracy isn't required.
   */
  previewQueue(count = 8) {
    const clones = this.aliveUnits().map((u) => ({
      uid: u.uid,
      id: u.id,
      name: u.name,
      isEnemy: u.isEnemy,
      ct: u.ctValue,
      agi: u.agility,
    }));
    if (clones.length === 0) return [];

    const queue = [];
    let guard = 0;
    while (queue.length < count && guard++ < 100000) {
      const ready = clones.filter((c) => c.ct >= BASE_THRESHOLD);
      if (ready.length === 0) {
        const ticksNeeded = clones.map((c) =>
          Math.ceil((BASE_THRESHOLD - c.ct) / Math.max(1, c.agi))
        );
        const jump = Math.max(1, Math.min(...ticksNeeded));
        clones.forEach((c) => {
          c.ct += c.agi * jump;
        });
        continue;
      }
      ready.sort((a, b) => (b.ct - a.ct) || (b.agi - a.agi));
      const actor = ready[0];
      queue.push({ uid: actor.uid, id: actor.id, name: actor.name, isEnemy: actor.isEnemy });
      actor.ct -= BASE_THRESHOLD * 1.0; // assume average-cost action for preview purposes
    }
    return queue;
  }
}

